package day1;

public class WeeklyAssignment6_Even_Odd {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("Even numbers:");
		for(int i=1;i<=20;i++) {
			if (i%2==0) {
				System.out.print(i+" ");
			}
		}
		System.out.print("\n");
		System.out.println("Odd numbers:");
		for(int i=1;i<=20;i++) {
			if (i%2!=0) {
				System.out.print(i+" ");
			}
		}
	
		

	}

}
